package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import com.fasterxml.jackson.databind.introspect.BeanProperty;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class StringCollectionDeserializer_createContextual_TriageGen2Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        typeFactory = TypeFactory.defaultInstance();
        collectionType = typeFactory.constructCollectionType(Collection.class, String.class);
        contentType = collectionType.getContentType();

        when(ctxt.getConfig()).thenReturn(ctxt.getCodec().getDeserializationConfig());
        when(ctxt.getSerializerProvider()).thenReturn(mock(SerializerProvider.class));
        when(property.getMember().getAnnotation(JsonFormat.class)).thenReturn(null);
    }

    @Test
    public void testCreateContextual_WithValueDeser_CallsHandleSecondaryContextualization() throws Exception {
        JsonDeserializer<?> valueDeser = mock(JsonDeserializer.class);
        StringCollectionDeserializer deserializer = new StringCollectionDeserializer(collectionType, valueDeser, null);

        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(valueDeser);

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).handleSecondaryContextualization(valueDeser, property, contentType);
    }

    @Test
    public void testCreateContextual_NoValueDeser_FindsConvertingContentDeserializer() throws Exception {
        StringCollectionDeserializer deserializer = new StringCollectionDeserializer(collectionType, null, null);

        // Mock finding a converter
        JsonDeserializer<?> converterDeser = mock(JsonDeserializer.class);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(converterDeser);

        // We need to mock the internal findConvertingContentDeserializer logic via ctxt or behavior
        // Since findConvertingContentDeserializer is protected/internal, we simulate the path where it returns null
        // by ensuring the context returns a value for the next step.

        // In the actual implementation, if findConvertingContentDeserializer returns null, it calls findContextualValueDeserializer
        // We simulate the 'valueDeser == null' path.

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).findContextualValueDeserializer(contentType, property);
    }

    @Test
    public void testCreateContextual_WithDelegateCreator() throws Exception {
        // Create a mock ValueInstantiator that has a delegate creator
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        AnnotatedWithParams delegateCreator = mock(AnnotatedWithParams.class);

        when(instantiator.getDelegateCreator()).thenReturn(delegateCreator);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        // Mock findDeserializer behavior indirectly if possible, 
        // however findDeserializer is a method of the class itself. 
        // Since we cannot easily mock 'this', we test the logic flow.

        StringCollectionDeserializer deserializer = new StringCollectionDeserializer(collectionType, null, instantiator);

        // This test covers the branch: if (_valueInstantiator != null) and (delegateCreator != null)
        // Note: findDeserializer is usually protected. In a real scenario, we'd use a spy or a subclass.
        StringCollectionDeserializer spyDeserializer = spy(deserializer);
        doReturn(mock(JsonDeserializer.class)).when(spyDeserializer).findDeserializer(any(), any(), any());
        doReturn(null).when(spyDeserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(any(), any())).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_IsDefaultDeserializer_ReturnsNullValueDeser() throws Exception {
        // A deserializer that returns true for isDefaultDeserializer
        JsonDeserializer<?> defaultDeser = new StdDeserializer<Object>(Object.class) {
            @Override
            public Object deserialize(JsonParser p, DeserializationContext ctxt) { return null; }
        };

        // We need a way to trigger isDefaultDeserializer(valueDeser) -> true
        // In Jackson, this usually checks if the deserializer is a standard one for the type.
        // For this test, we'll use a spy to force the branch.

        StringCollectionDeserializer deserializer = new StringCollectionDeserializer(collectionType, defaultDeser, null);
        StringCollectionDeserializer spyDeserializer = spy(deserializer);

        doReturn(true).when(spyDeserializer).isDefaultDeserializer(any());
        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(defaultDeser);

        JsonDeserializer<?> result = spyDeserializer.createContextual(ctxt, property);

        // If isDefaultDeserializer is true, valueDeser becomes null in the result
        // The result is created via withResolved(delegate, null, nuller, unwrapSingle)
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_NoInstantiator() throws Exception {
        StringCollectionDeserializer deserializer = new StringCollectionDeserializer(collectionType, null, null);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = deserializer.createContextual(ctxt, property);
        assertNotNull(result);
    }

    // Helper interface to match the internal class structure for mocking
    private interface AnnotatedWithParams extends Annotated {
        // This is a placeholder for the internal Jackson interface used in the method
    }
}
